import { motion } from "framer-motion";
import { PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { FolderGit2, Flame, CalendarCheck, Zap } from "lucide-react";
import SectionHeading from "./SectionHeading";
import CountUp from "./CountUp";
import { PIE_COLORS } from "../data/portfolio";

const LEVEL_COLORS = ["rgba(255,255,255,.07)", "rgba(16,185,129,.25)", "rgba(16,185,129,.45)", "#10B981", "#6EE7B7"];
const TOOLTIP_STYLE = { background: "#141419", border: "1px solid rgba(255,255,255,.1)", borderRadius: 12, color: "#E4E4E7", fontSize: 13 };

export default function GitHubStats({ github }) {
  const c = github?.contributions ?? {};
  const months = c.months ?? [];
  const heat = c.heat ?? [];
  const languages = c.languages ?? [];
  const weeks = [];
  for (let i = 0; i < heat.length; i += 7) weeks.push(heat.slice(i, i + 7));

  const statCards = [
    { label: "Public Repositories", value: github?.user?.public_repos ?? 0, icon: FolderGit2, color: "#34D399", testId: "stat-card-repos" },
    { label: "Contributions · 2026", value: c.total_year ?? 0, icon: Flame, color: "#38BDF8", testId: "stat-card-contributions" },
    { label: "Active Days", value: c.active_days ?? 0, icon: CalendarCheck, color: "#94A3B8", testId: "stat-card-active-days" },
    { label: "Best Day Streak", value: c.best_day ?? 0, icon: Zap, color: "#FBBF24", testId: "stat-card-best-day" },
  ];

  return (
    <section id="stats" className="relative scroll-mt-24 py-20 md:py-28">
      <div className="mx-auto max-w-7xl px-6">
        <SectionHeading
          eyebrow="github_analytics"
          title="GitHub"
          highlight="Stats"
          sub="Live numbers pulled straight from my GitHub profile and contribution history."
        />

        <div className="mt-12 grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-12" data-testid="stats-bento">
          {statCards.map((s, i) => (
            <motion.div
              key={s.label}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, amount: 0.3 }}
              transition={{ duration: 0.5, delay: i * 0.07 }}
              data-testid={s.testId}
              className="glass rounded-2xl p-6 transition-colors duration-300 hover:border-white/20 lg:col-span-3"
            >
              <span className="grid h-11 w-11 place-items-center rounded-xl border border-white/5" style={{ background: `${s.color}14` }}>
                <s.icon className="h-5 w-5" style={{ color: s.color }} />
              </span>
              <div className="mt-4 font-display text-4xl font-black text-white">
                <CountUp value={s.value} />
              </div>
              <div className="mt-1 text-xs uppercase tracking-wider text-zinc-500">{s.label}</div>
            </motion.div>
          ))}

          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.6 }}
            className="glass rounded-3xl p-6 lg:col-span-8"
            data-testid="stats-contribution-chart"
          >
            <h3 className="font-display text-lg font-bold text-white">Contribution Activity</h3>
            {months.length > 0 ? (
              <div className="mt-4 h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={months} margin={{ top: 8, right: 8, left: -16, bottom: 0 }}>
                    <defs>
                      <linearGradient id="barGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#34D399" />
                        <stop offset="100%" stopColor="#0F766E" />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,.06)" vertical={false} />
                    <XAxis dataKey="month" tick={{ fill: "#71717A", fontSize: 11 }} axisLine={false} tickLine={false} />
                    <YAxis tick={{ fill: "#71717A", fontSize: 11 }} axisLine={false} tickLine={false} allowDecimals={false} width={32} />
                    <Tooltip contentStyle={TOOLTIP_STYLE} cursor={{ fill: "rgba(255,255,255,.05)" }} />
                    <Bar dataKey="count" fill="url(#barGrad)" radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <p className="mt-24 text-center text-sm text-zinc-500">Contribution chart is warming up — check back soon.</p>
            )}
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.6, delay: 0.1 }}
            className="glass rounded-3xl p-6 lg:col-span-4"
            data-testid="stats-language-donut"
          >
            <h3 className="font-display text-lg font-bold text-white">Language Distribution</h3>
            {languages.length > 0 ? (
              <div className="relative mt-4 h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={languages} dataKey="value" nameKey="name" innerRadius={65} outerRadius={95} paddingAngle={4} stroke="none">
                      {languages.map((_, i) => (
                        <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={TOOLTIP_STYLE} />
                  </PieChart>
                </ResponsiveContainer>
                <div className="pointer-events-none absolute inset-0 grid place-items-center">
                  <div className="text-center">
                    <div className="font-display text-2xl font-black text-white">{github?.user?.public_repos ?? 0}</div>
                    <div className="text-xs text-zinc-500">repos</div>
                  </div>
                </div>
              </div>
            ) : (
              <p className="mt-24 text-center text-sm text-zinc-500">Language data will appear as repositories grow.</p>
            )}
            <div className="mt-2 flex flex-wrap justify-center gap-3">
              {languages.map((l, i) => (
                <span key={l.name} className="flex items-center gap-1.5 text-xs text-zinc-400">
                  <span className="h-2.5 w-2.5 rounded-full" style={{ background: PIE_COLORS[i % PIE_COLORS.length] }} />
                  {l.name}
                </span>
              ))}
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.6 }}
            className="glass rounded-3xl p-6 lg:col-span-12"
            data-testid="stats-heatmap"
          >
            <h3 className="font-display text-lg font-bold text-white">Contribution Grid</h3>
            {weeks.length > 0 ? (
              <div className="mt-5 overflow-x-auto pb-2">
                <div className="flex min-w-max gap-1">
                  {weeks.map((week, wi) => (
                    <div key={wi} className="flex flex-col gap-1">
                      {week.map((day) => (
                        <span
                          key={day.date}
                          title={`${day.date}: ${day.count} contributions`}
                          className="h-3 w-3 rounded-[3px] transition-transform hover:scale-125"
                          style={{ background: LEVEL_COLORS[day.level] || LEVEL_COLORS[0] }}
                        />
                      ))}
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <p className="mt-6 text-center text-sm text-zinc-500">Contribution grid is warming up — check back soon.</p>
            )}
            <div className="mt-4 flex items-center justify-end gap-2 text-xs text-zinc-500">
              Less
              {LEVEL_COLORS.map((cl, i) => (
                <span key={i} className="h-3 w-3 rounded-[3px]" style={{ background: cl }} />
              ))}
              More
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
