import { useRef, useState } from "react";

export default function TiltCard({ children, className = "", max = 10, testId }) {
  const ref = useRef(null);
  const [transform, setTransform] = useState("perspective(1000px)");
  const [pos, setPos] = useState({ x: 50, y: 50, opacity: 0 });

  const onMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width;
    const py = (e.clientY - rect.top) / rect.height;
    setTransform(
      `perspective(1000px) rotateX(${(0.5 - py) * max}deg) rotateY(${(px - 0.5) * max}deg) scale3d(1.02, 1.02, 1.02)`
    );
    setPos({ x: px * 100, y: py * 100, opacity: 1 });
  };

  const onLeave = () => {
    setTransform("perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)");
    setPos((p) => ({ ...p, opacity: 0 }));
  };

  return (
    <div
      ref={ref}
      data-testid={testId}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      className={`relative transition-transform duration-200 ease-out will-change-transform ${className}`}
      style={{ transform }}
    >
      {children}
      <div
        className="pointer-events-none absolute inset-0 rounded-[inherit] transition-opacity duration-300"
        style={{
          opacity: pos.opacity,
          background: `radial-gradient(circle at ${pos.x}% ${pos.y}%, rgba(255,255,255,0.14), transparent 55%)`,
        }}
      />
    </div>
  );
}
