import { useState } from "react";
import { motion } from "framer-motion";
import { Terminal } from "lucide-react";

const TABS = [
  { name: "waheed.js", lang: "js" },
  { name: "skills.json", lang: "json" },
  { name: "passion.py", lang: "py" },
];

const CODE = {
  js: [
    'const waheed = {',
    '  name: "Mohammed Waheeduddin",',
    '  handle: "@Waheed-Web",',
    '  role: "Full-Stack Web Developer",',
    '  stack: ["React", "Next.js", "Node.js"],',
    '  location: "Hyderabad, IN",',
    '  openToFreelance: true',
    '};',
    '',
    'export default waheed;',
  ],
  json: [
    '{',
    '  "frontend": ["React", "Next.js", "Tailwind"],',
    '  "backend": ["Node.js", "Express", "MongoDB"],',
    '  "tools": ["Git", "GitHub", "VS Code"],',
    '  "mission": "pixel-perfect web apps",',
    '  "coffee": Infinity',
    '}',
  ],
  py: [
    'def build(idea):',
    '    design = craft_ui(idea, pixel_perfect=True)',
    '    backend = power_with("Node.js", "MongoDB")',
    '    return ship(design + backend, with_love=True)',
    '',
    'build("your next big thing")',
  ],
};

const KEYWORDS = new Set(["const", "let", "export", "default", "function", "return", "def", "True", "False", "Infinity", "await", "new"]);

function renderLine(line, lineIdx) {
  const pieces = line.split(/("[^"]*"|'[^']*')/g);
  return pieces.map((p, idx) => {
    const key = `${lineIdx}-${idx}`;
    if (/^["']/.test(p)) return <span key={key} className="text-emerald-300">{p}</span>;
    const words = p.split(/\b(const|let|export|default|function|return|def|True|False|Infinity|await|new)\b/g);
    return words.map((k, j) =>
      KEYWORDS.has(k) ? (
        <span key={`${key}-${j}`} className="text-sky-300">{k}</span>
      ) : (
        <span key={`${key}-${j}`} className="text-zinc-300">{k}</span>
      )
    );
  });
}

export default function CodeWindow() {
  const [active, setActive] = useState("js");

  return (
    <div className="overflow-hidden rounded-2xl border border-white/10 bg-[#0C0C11]/95 shadow-[0_20px_60px_rgba(0,0,0,.5)] backdrop-blur-xl" data-testid="about-code-window">
      <div className="flex items-center gap-2 border-b border-white/10 px-4 py-3">
        <span className="h-3 w-3 rounded-full bg-[#FF5F57]" />
        <span className="h-3 w-3 rounded-full bg-[#FEBC2E]" />
        <span className="h-3 w-3 rounded-full bg-[#28C840]" />
        <Terminal className="ml-3 h-3.5 w-3.5 text-zinc-600" />
        <span className="font-mono text-xs text-zinc-600">~/waheed-portfolio</span>
      </div>
      <div className="flex gap-1 border-b border-white/10 px-3 pt-2">
        {TABS.map((t) => (
          <button
            key={t.lang}
            data-testid={`code-tab-${t.lang}`}
            onClick={() => setActive(t.lang)}
            className={`rounded-t-lg px-4 py-2 font-mono text-xs transition-colors ${
              active === t.lang ? "bg-white/10 text-emerald-300" : "text-zinc-500 hover:text-zinc-300"
            }`}
          >
            {t.name}
          </button>
        ))}
      </div>
      <motion.pre
        key={active}
        initial="hidden"
        animate="show"
        variants={{ show: { transition: { staggerChildren: 0.05 } } }}
        className="overflow-x-auto p-5 font-mono text-[13px] leading-7"
      >
        {CODE[active].map((line, i) => (
          <motion.div key={i} variants={{ hidden: { opacity: 0, x: -8 }, show: { opacity: 1, x: 0 } }} className="flex">
            <span className="w-8 select-none text-right text-zinc-700">{i + 1}</span>
            <code className="pl-4">{renderLine(line, i)}</code>
          </motion.div>
        ))}
      </motion.pre>
    </div>
  );
}
