import { useEffect, useState } from "react";
import { motion, useScroll, useTransform } from "framer-motion";
import { Github, MapPin, ArrowDown, Sparkles, Eye } from "lucide-react";
import TiltCard from "./TiltCard";
import CountUp from "./CountUp";
import { PROFILE } from "../data/portfolio";

const RESUME_URL = `${process.env.PUBLIC_URL || ""}/resume.pdf`;

const ROLES = [
  "Full-Stack Web Developer",
  "React & Next.js Specialist",
  "Modern Websites & Web Apps",
  "Node.js Backend Builder",
];

function useTypewriter(words) {
  const [i, setI] = useState(0);
  const [txt, setTxt] = useState("");
  const [del, setDel] = useState(false);

  useEffect(() => {
    const word = words[i % words.length];
    let t;
    if (!del && txt === word) t = setTimeout(() => setDel(true), 1700);
    else if (del && txt === "") {
      setDel(false);
      setI((v) => (v + 1) % words.length);
    } else {
      t = setTimeout(() => setTxt(word.slice(0, txt.length + (del ? -1 : 1))), del ? 35 : 75);
    }
    return () => clearTimeout(t);
  }, [txt, del, i, words]);

  return txt;
}

function VisitorCounter() {
  const [count, setCount] = useState(null);

  useEffect(() => {
    fetch("https://abacus.jasoncameron.dev/hit/waheed-dev-portfolio/views")
      .then((r) => r.json())
      .then((d) => {
        if (typeof d?.value === "number") setCount(d.value);
      })
      .catch(() => {});
  }, []);

  if (count === null) return null;
  return (
    <div className="glass inline-flex items-center gap-2 rounded-full px-4 py-2 text-xs text-zinc-300" data-testid="visitor-counter">
      <Eye className="h-4 w-4 text-emerald-300" />
      <span>
        <b className="font-semibold text-white">{count.toLocaleString()}</b> visits and counting
      </span>
    </div>
  );
}

