import { useState } from "react";
import { motion } from "framer-motion";
import axios from "axios";
import { toast } from "sonner";
import { MapPin, Github, BadgeCheck, Send, Loader2, Mail } from "lucide-react";
import SectionHeading from "./SectionHeading";
import { API, FORMSPREE_ENDPOINT, PROFILE } from "../data/portfolio";

export default function Contact() {
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" });
  const [sending, setSending] = useState(false);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const contactEmail = process.env.REACT_APP_CONTACT_EMAIL || "";

  const submit = async (e) => {
    e.preventDefault();
    setSending(true);
    try {
      if (FORMSPREE_ENDPOINT) {
        await axios.post(
          FORMSPREE_ENDPOINT,
          { ...form, _subject: form.subject || "New message from your portfolio", _captcha: "false" },
          { headers: { Accept: "application/json" } }
        );
      } else {
        await axios.post(`${API}/contact`, form);
      }
      toast.success("Message sent successfully! I will get back to you soon.");
      setForm({ name: "", email: "", subject: "", message: "" });
    } catch (err) {
      toast.error(
        err?.response?.data?.detail ||
          err?.response?.data?.errors?.[0]?.message ||
          "Something went wrong. Please try again."
      );
    } finally {
      setSending(false);
    }
  };

  const INFO = [
    { icon: MapPin, label: "Location", value: "Serlingampally, BHEL · Hyderabad, India", href: null, testId: "contact-info-location" },
    { icon: Github, label: "GitHub", value: "github.com/Waheed-Web", href: PROFILE.githubUrl, testId: "contact-info-github" },
    {
      icon: BadgeCheck,
      label: "Availability",
      value: "Open for freelance projects",
      href: null,
      testId: "contact-info-availability",
    },
  ];

  const inputCls =
    "w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3 text-sm text-white placeholder-zinc-600 outline-none transition-colors focus:border-emerald-400/60 focus:ring-2 focus:ring-emerald-400/15";

  return (
    <section id="contact" className="relative scroll-mt-24 py-20 md:py-28">
      <div className="absolute inset-0 bg-grid" aria-hidden="true" />
      <div className="relative mx-auto max-w-7xl px-6">
        <SectionHeading
          eyebrow="say_hello"
          title="Get In"
          highlight="Touch"
          sub="Have a project in mind? Drop a message — it lands straight in my inbox."
        />
        <div className="mt-14 grid gap-10 lg:grid-cols-[.9fr_1.1fr]">
          <motion.div
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.7 }}
            className="space-y-4"
            data-testid="contact-info-cards"
          >
            {INFO.map((item) => {
              const Icon = item.icon;
              const inner = (
                <div className="glass flex items-center gap-4 rounded-2xl p-5 transition-colors duration-300 hover:border-emerald-400/30">
                  <span className="grid h-12 w-12 place-items-center rounded-xl border border-white/5 bg-emerald-400/10">
                    <Icon className="h-5 w-5 text-emerald-300" />
                  </span>
                  <div>
                    <div className="text-xs uppercase tracking-wider text-zinc-500">{item.label}</div>
                    <div className="mt-0.5 text-sm font-medium text-zinc-200">{item.value}</div>
                  </div>
                </div>
              );
              return item.href ? (
                <a key={item.label} href={item.href} target="_blank" rel="noreferrer" data-testid={item.testId} className="block">
                  {inner}
                </a>
              ) : (
                <div key={item.label} data-testid={item.testId}>
                  {inner}
                </div>
              );
            })}
            {contactEmail && (
              <a href={`mailto:${contactEmail}`} data-testid="contact-email-button" className="glass flex items-center gap-4 rounded-2xl p-5 transition-colors duration-300 hover:border-emerald-400/30">
                <span className="grid h-12 w-12 place-items-center rounded-xl border border-white/5 bg-emerald-400/10">
                  <Mail className="h-5 w-5 text-emerald-300" />
                </span>
                <div>
                  <div className="text-xs uppercase tracking-wider text-zinc-500">Email</div>
                  <div className="mt-0.5 text-sm font-medium text-zinc-200">Write to me directly</div>
                </div>
              </a>
            )}
            <div className="glass rounded-2xl p-6" data-testid="contact-quote-card">
              <p className="font-mono text-sm leading-relaxed text-zinc-400">
                <span className="text-sky-300">const</span> <span className="text-zinc-200">nextProject</span> ={" "}
                <span className="text-emerald-300">&quot;yours&quot;</span>;
              </p>
              <p className="mt-3 text-sm text-zinc-400">Let&apos;s turn your idea into a fast, reliable, modern web experience.</p>
            </div>
          </motion.div>

          <motion.form
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.7 }}
            onSubmit={submit}
            className="glass rounded-3xl p-6 sm:p-8"
            data-testid="contact-form"
          >
            <div className="grid gap-4 sm:grid-cols-2">
              <div>
                <label htmlFor="contact-name" className="mb-1.5 block text-xs font-medium text-zinc-400">Name</label>
                <input
                  id="contact-name"
                  data-testid="contact-name-input"
                  required
                  minLength={2}
                  value={form.name}
                  onChange={set("name")}
                  placeholder="Your name"
                  className={inputCls}
                />
              </div>
              <div>
                <label htmlFor="contact-email" className="mb-1.5 block text-xs font-medium text-zinc-400">Email</label>
                <input
                  id="contact-email"
                  data-testid="contact-email-input"
                  type="email"
                  required
                  value={form.email}
                  onChange={set("email")}
                  placeholder="you@example.com"
                  className={inputCls}
                />
              </div>
            </div>
            <div className="mt-4">
              <label htmlFor="contact-subject" className="mb-1.5 block text-xs font-medium text-zinc-400">Subject</label>
              <input
                id="contact-subject"
                data-testid="contact-subject-input"
                value={form.subject}
                onChange={set("subject")}
                placeholder="What's this about?"
                className={inputCls}
              />
            </div>
            <div className="mt-4">
              <label htmlFor="contact-message" className="mb-1.5 block text-xs font-medium text-zinc-400">Message</label>
              <textarea
                id="contact-message"
                data-testid="contact-message-input"
                required
                minLength={10}
                rows={5}
                value={form.message}
                onChange={set("message")}
                placeholder="Tell me about your project..."
                className={`${inputCls} resize-none`}
              />
            </div>
            <button
              type="submit"
              data-testid="contact-submit-button"
              disabled={sending}
              className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-full bg-white px-8 py-3.5 font-semibold text-zinc-900 transition-colors hover:bg-zinc-200 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {sending ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" /> Sending...
                </>
              ) : (
                <>
                  <Send className="h-4 w-4" /> Send Message
                </>
              )}
            </button>
            <p className="mt-3 text-center text-xs text-zinc-600" data-testid="contact-form-note">
              Messages land straight in Waheed&apos;s inbox.
            </p>
          </motion.form>
        </div>
      </div>
    </section>
  );
}
