import { useRef, useState } from "react";
import { motion } from "framer-motion";
import { ChevronLeft, ChevronRight, ExternalLink, Camera } from "lucide-react";
import SectionHeading from "./SectionHeading";

export default function DarkroomGallery({ github }) {
  const repos = (github?.repos ?? []).filter((r) => r.homepage);
  const [broken, setBroken] = useState({});
  const scroller = useRef(null);
  const visible = repos.filter((r) => !broken[r.name]);

  const scrollBy = (dir) => {
    scroller.current?.scrollBy({ left: dir * 440, behavior: "smooth" });
  };

  return (
    <section id="gallery" className="relative scroll-mt-24 py-20 md:py-28">
      <div className="mx-auto max-w-7xl px-6">
        <SectionHeading
          eyebrow="the_darkroom"
          title="Site"
          highlight="Gallery"
          sub="Every site I ship, framed — captured fresh from the live web on each deploy. Hover to develop them into full colour."
        />
        {visible.length > 0 ? (
          <>
            <div className="mt-10 flex justify-end gap-2">
              <button
                data-testid="gallery-prev-button"
                onClick={() => scrollBy(-1)}
                aria-label="Previous sites"
                className="grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-white/5 text-zinc-300 transition-colors hover:border-emerald-400/50 hover:text-emerald-300"
              >
                <ChevronLeft className="h-4 w-4" />
              </button>
              <button
                data-testid="gallery-next-button"
                onClick={() => scrollBy(1)}
                aria-label="Next sites"
                className="grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-white/5 text-zinc-300 transition-colors hover:border-emerald-400/50 hover:text-emerald-300"
              >
                <ChevronRight className="h-4 w-4" />
              </button>
            </div>
            <div
              ref={scroller}
              className="mt-5 flex snap-x snap-mandatory gap-6 overflow-x-auto pb-4"
              data-testid="gallery-track"
            >
              {visible.map((r, i) => (
                <motion.figure
                  key={r.name}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true, amount: 0.2 }}
                  transition={{ duration: 0.55, delay: (i % 3) * 0.08 }}
                  className="w-[85%] shrink-0 snap-center sm:w-[460px]"
                  data-testid={`gallery-item-${r.name}`}
                >
                  <div className="glass rounded-2xl p-3">
                    <div className="relative overflow-hidden rounded-xl">
                      <img
                        src={`${process.env.PUBLIC_URL || ""}/shots/${r.name}.jpg`}
                        alt={`${r.name} live screenshot`}
                        loading="lazy"
                        onError={() => setBroken((b) => ({ ...b, [r.name]: true }))}
                        className="w-full object-cover object-top grayscale-[0.85] transition-all duration-700 hover:grayscale-0 hover:scale-[1.02]"
                        style={{ aspectRatio: "16 / 10" }}
                      />
                      <span className="absolute left-3 top-3 flex items-center gap-1.5 rounded-full bg-black/60 px-2.5 py-1 font-mono text-[10px] text-emerald-300 backdrop-blur">
                        <Camera className="h-3 w-3" /> LIVE CAPTURE
                      </span>
                    </div>
                    <figcaption className="flex items-center justify-between px-2 pb-1 pt-3">
                      <span className="font-display text-sm font-bold text-white">{r.name.replace(/-/g, " ")}</span>
                      <a
                        href={r.homepage}
                        target="_blank"
                        rel="noreferrer"
                        data-testid={`gallery-link-${i}`}
                        className="inline-flex items-center gap-1 text-xs font-medium text-emerald-300 hover:text-emerald-200"
                      >
                        Visit site <ExternalLink className="h-3 w-3" />
                      </a>
                    </figcaption>
                  </div>
                </motion.figure>
              ))}
            </div>
          </>
        ) : (
          <p className="mt-12 text-center text-sm text-zinc-500" data-testid="gallery-empty-state">
            New sites will develop here automatically as they ship.
          </p>
        )}
      </div>
    </section>
  );
}
