import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronDown, NotebookPen } from "lucide-react";
import SectionHeading from "./SectionHeading";
import { BLOG_POSTS } from "../data/blog";

export default function BlogSection() {
  const [open, setOpen] = useState(BLOG_POSTS[0]?.slug ?? null);

  return (
    <section id="blog" className="relative scroll-mt-24 py-20 md:py-28">
      <div className="mx-auto max-w-4xl px-6">
        <SectionHeading
          eyebrow="learning_log"
          title="What I'm"
          highlight="Learning"
          sub="A public log of lessons from every project I ship — growing as I grow."
        />
        <div className="mt-12 space-y-4" data-testid="blog-post-list">
          {BLOG_POSTS.map((post, idx) => {
            const isOpen = open === post.slug;
            return (
              <motion.article
                key={post.slug}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.2 }}
                transition={{ duration: 0.5, delay: idx * 0.07 }}
                className="glass overflow-hidden rounded-2xl transition-colors duration-300 hover:border-white/20"
                data-testid={`blog-post-${post.slug}`}
              >
                <button
                  onClick={() => setOpen(isOpen ? null : post.slug)}
                  data-testid={`blog-toggle-${post.slug}`}
                  className="flex w-full items-center justify-between gap-4 p-6 text-left"
                >
                  <div>
                    <div className="flex flex-wrap items-center gap-3">
                      <span className="font-mono text-xs text-emerald-300">{post.date}</span>
                      {post.tags.map((t) => (
                        <span key={t} className="rounded-full border border-white/10 bg-white/5 px-2.5 py-0.5 font-mono text-xs text-zinc-400">
                          {t}
                        </span>
                      ))}
                    </div>
                    <h3 className="mt-2.5 font-display text-lg font-bold text-white">{post.title}</h3>
                    {!isOpen && <p className="mt-1.5 text-sm text-zinc-400">{post.excerpt}</p>}
                  </div>
                  <motion.span animate={{ rotate: isOpen ? 180 : 0 }} className="shrink-0 text-zinc-500">
                    <ChevronDown className="h-5 w-5" />
                  </motion.span>
                </button>
                <AnimatePresence initial={false}>
                  {isOpen && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.35, ease: "easeInOut" }}
                    >
                      <div className="space-y-4 border-t border-white/10 px-6 pb-6 pt-5" data-testid={`blog-body-${post.slug}`}>
                        {post.body.map((p, i) => (
                          <p key={i} className="text-sm leading-relaxed text-zinc-400">
                            {p}
                          </p>
                        ))}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.article>
            );
          })}
        </div>
        <p className="mt-8 flex items-center justify-center gap-2 text-center text-xs text-zinc-600" data-testid="blog-footer-note">
          <NotebookPen className="h-3.5 w-3.5" /> New entries land here after every shipped project.
        </p>
      </div>
    </section>
  );
}
