const MONTH_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function buildGithubPayload(user, repos, daily) {
  const monthsAcc = {};
  let activeDays = 0;
  let bestDay = 0;
  for (const d of daily) {
    const key = d.date.slice(0, 7);
    monthsAcc[key] = (monthsAcc[key] || 0) + d.count;
    if (d.count > 0) activeDays += 1;
    bestDay = Math.max(bestDay, d.count);
  }
  const months = Object.keys(monthsAcc)
    .sort()
    .map((k) => ({ month: MONTH_ABBR[parseInt(k.slice(5, 7), 10) - 1], count: monthsAcc[k] }));
  const heat = daily.slice(-182).map((d) => ({ date: d.date, count: d.count, level: d.level }));
  const langAcc = {};
  for (const r of repos) {
    const l = r.language;
    if (l) langAcc[l] = (langAcc[l] || 0) + 1;
  }
  const languages = Object.entries(langAcc).map(([name, value]) => ({ name, value }));
  return {
    user: {
      login: user.login,
      name: user.name || user.login,
      avatar_url: user.avatar_url,
      bio: user.bio,
      location: user.location,
      public_repos: user.public_repos || 0,
      followers: user.followers || 0,
      created_at: user.created_at,
      html_url: user.html_url,
    },
    repos: repos.map((r) => ({
      name: r.name,
      description: r.description || "",
      language: r.language,
      stars: r.stargazers_count || 0,
      forks: r.forks_count || 0,
      html_url: r.html_url,
      homepage: r.homepage || "",
      topics: (r.topics || []).slice(0, 6),
      pushed_at: r.pushed_at,
    })),
    contributions: {
      total_year: Object.values(monthsAcc).reduce((a, b) => a + b, 0),
      active_days: activeDays,
      best_day: bestDay,
      months,
      heat,
      languages,
    },
  };
}

