import React, { useEffect, useState } from "react";
import { BrowserRouter, useLocation } from "react-router-dom";
import Lenis from "lenis";
import axios from "axios";
import { Toaster } from "sonner";
import ParticleBackground from "./components/ParticleBackground";
import FloatingShapes from "./components/FloatingShapes";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Marquee from "./components/Marquee";
import About from "./components/About";
import Skills from "./components/Skills";
import Projects from "./components/Projects";
import DarkroomGallery from "./components/DarkroomGallery";
import GitHubStats from "./components/GitHubStats";
import Timeline from "./components/Timeline";
import BlogSection from "./components/BlogSection";
import Contact from "./components/Contact";
import Footer from "./components/Footer";
import { FALLBACK_GITHUB, buildGithubPayload } from "./data/portfolio";

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="grid min-h-screen place-items-center bg-[#0A0A0C] p-6 text-center text-zinc-300">
          <div>
            <p className="font-display text-xl font-bold text-white">Something went wrong.</p>
            <button onClick={() => window.location.reload()} className="mt-4 rounded-full bg-white px-6 py-2.5 text-sm font-semibold text-zinc-900" data-testid="error-reload-button">
              Reload
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
}

function Portfolio() {
  const [github, setGithub] = useState(FALLBACK_GITHUB);

  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const lenis = new Lenis({ duration: 1.15, smoothWheel: true });
    document.documentElement.style.scrollBehavior = "auto";
    let raf;
    const loop = (t) => {
      lenis.raf(t);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    const onClick = (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a) return;
      const href = a.getAttribute("href");
      if (href.length > 1 && document.querySelector(href)) {
        e.preventDefault();
        lenis.scrollTo(href, { offset: -80 });
      }
    };
    document.addEventListener("click", onClick);
    return () => {
      cancelAnimationFrame(raf);
      lenis.destroy();
      document.removeEventListener("click", onClick);
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      try {
        const [u, r, c] = await Promise.all([
          axios.get("https://api.github.com/users/Waheed-Web"),
          axios.get("https://api.github.com/users/Waheed-Web/repos?per_page=100&sort=updated"),
          axios.get("https://github-contributions-api.jogruber.de/v4/Waheed-Web"),
        ]);
        if (!cancelled) {
          setGithub(buildGithubPayload(u.data, r.data, (c.data && c.data.contributions) || []));
        }
      } catch (e) {
        /* live data unavailable — embedded fallback stays */
      }
    };
    run();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="relative min-h-screen overflow-x-hidden bg-[#0A0A0C] font-body text-zinc-300">
      <ParticleBackground />
      <FloatingShapes />
      <Navbar />
      <main className="relative z-10">
        <Hero github={github} />
        <Marquee />
        <About />
        <Skills />
        <Projects github={github} />
        <DarkroomGallery github={github} />
        <GitHubStats github={github} />
        <Timeline />
        <BlogSection />
        <Contact />
      </main>
      <div className="relative z-10">
        <Footer />
      </div>
      <Toaster position="bottom-right" richColors theme="dark" />
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <ScrollToTop />
      <ErrorBoundary>
        <Portfolio />
      </ErrorBoundary>
    </BrowserRouter>
  );
}
